const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','midi.js','manual-loops.js','beatgrid.js','midi-manual-scratch-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f)).arrayBuffer())])));
async function until(fn,label,ms=12000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);};
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`;
function add(target,ch,n){field('#midi-target',target);field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding','7-bit absolute');click('#midi-add');}
function send(ch,n,value=127){field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');}
function press(ch,n){send(ch,n);send(ch,n,0);}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const crossings=[],start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=data.length&&end>start,'Invalid measurement window');for(let i=start;i<end;i++){power+=data[i]**2;if(i>start&&data[i-1]<0&&data[i]>=0)crossings.push((i-1-data[i-1]/(data[i]-data[i-1]))/sr);}return{from,to,rms:Math.sqrt(power/(end-start)),hz:crossings.length>3?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){
 $('#manual-run').disabled=true;const {engine,state}=app,d=state.decks[0],other=state.decks[1],original=d.track,opposite=other.track,sample=state.tracks.find(t=>t.id!==original.id&&t.id!==opposite.id);
 const report={startedAt:new Date().toISOString(),completed:false,scope:'Actual app MIDI editor/synthetic messages, manual loop audio and Scratch Bank UI/loads. No physical, native, full loop/range/persistence/compound/reference acceptance.',criteria:{frequencyErrorHz:.8,playingMinimumRMS:.005,loopBoundaryToleranceSeconds:1e-6,reloopPositionToleranceSeconds:.08},events:[],checks:[],errors:[]};
 const event=name=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted};report.events.push(e);return e;};
 const change=(s,v)=>{const el=$(s);assert(el,'Missing '+s);if(el.type==='checkbox')el.checked=v;else el.value=String(v);el.dispatchEvent(new Event('change',{bubbles:true}));};
 const jog=value=>{field('#midi-type','CC');field('#midi-channel',2);field('#midi-number',9);field('#midi-test-value',value);click('#midi-send');};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');state.settings['Lock Playing Deck']=false;
  for(const [track,channel,freq]of [[original,0,400],[opposite,1,550],[sample,0,800]]){const b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*12,engine.ctx.sampleRate),a=b.getChannelData(channel);for(let i=0;i<a.length;i++)a[i]=.12*Math.sin(2*Math.PI*freq*i/engine.ctx.sampleRate);engine.buffers.set(track.id,b);Object.assign(track,{bpm:120,grid:0,gridWarpMarkers:[],duration:12,analyzed:true,sampleGain:0,cues:[{position:2,name:'Cue 1'}],savedLoops:[]});}
  for(const deck of [d,other]){Object.assign(deck,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,loopIn:0,loopOut:0,loopSlot:0,loopEdit:null,stemSlip:'off',slip:false,sync:false,quantize:false,level:.8});engine.clearDeckScratchCache(deck.index);engine.mix(deck.index,'level',.8);}
  state.selected=sample.id;click('[data-panel="scratch"]');click('[data-scratch="7:assign"]');change('[data-scratch-start="7"]','Cue 1');change('[data-scratch-repeat="7"]',true);assert(state.scratch[0][7].track===sample.id,'Scratch Bank UI assignment failed');
  click('[data-panel="midi"]');click('#midi-reset');for(let n=0;n<7;n++)add(`Deck 1 manual loop pad ${n+1}`,7,96+n);add('Deck 1 scratch bank pad 8',7,119);add('Deck 1 scratch bank previous pad 8',7,127);field('#midi-target','Deck 1 jog bend');field('#midi-type','CC');field('#midi-channel',2);field('#midi-number',9);field('#midi-encoding','Relative two’s complement');click('#midi-add');
  await engine.seek(d,1);press(7,96);await until(()=>d.loopIn===1,'Loop In');await engine.seek(d,2);press(7,97);await until(()=>d.loop&&d.loopOut===2,'Loop Out');click('#modal-close');click(button(0,'play'));click(button(1,'play'));await until(()=>d.playing&&other.playing,'Two actual decks');click('[data-panel="midi"]');await engine.recordStart();event('record-start');
  press(7,96);await until(()=>d.loopEdit==='in','In edit mode');assert($(button(0,'loopIn')).getAttribute('aria-pressed')==='true','In edit ARIA state');jog(25);await until(()=>Math.abs(d.loopIn-1.025)<1e-6,'Jog In adjustment');press(7,96);await until(()=>!d.loopEdit,'In commit');press(7,97);await until(()=>d.loopEdit==='out','Out edit mode');jog(78);await until(()=>Math.abs(d.loopOut-1.95)<1e-6,'Jog Out adjustment');press(7,97);await until(()=>!d.loopEdit,'Out commit');report.manual={start:d.loopIn,end:d.loopOut,nominalRate:d.rate};assert(d.rate===1,'Boundary jog changed tempo');const edited=event('edited-loop');await sleep(300);
  press(7,102);await until(()=>original.savedLoops[0],'Save selected slot1');press(7,101);await until(()=>d.loopSlot===1,'Next slot');press(7,102);await until(()=>original.savedLoops[1],'Save selected slot2');press(7,100);await until(()=>d.loopSlot===0,'Previous slot');const saved=JSON.parse(localStorage.getItem('openplay-review-v1')).tags[original.id].savedLoops;assert(saved[0].start===1.025&&saved[1].end===1.95,'Saved loop metadata not persisted');report.savedLoops=saved;
  press(7,98);await until(()=>!d.loop,'Manual toggle off');press(7,99);await until(()=>d.loop&&engine.position(d)<1.105,'Reloop');report.reloop=engine.position(d);await sleep(220);
  click('#modal-close');click(button(0,'play'));await until(()=>!d.playing,'Pause original');const previousPosition=engine.position(d);click('[data-panel="midi"]');press(7,119);await until(()=>d.track===sample&&d.repeat&&!d.processing,'Scratch Bank cue load');report.scratch={id:d.track.id,position:engine.position(d),repeat:d.repeat,keylock:d.keylock,oppositeUnchanged:other.track===opposite&&other.playing};assert(report.scratch.position===2&&report.scratch.oppositeUnchanged,'Scratch Bank wrong cue/deck');click('#modal-close');click(button(0,'play'));await until(()=>d.playing,'Play loaded Scratch Bank sample');click('[data-panel="midi"]');const samplePlaying=event('scratch-sample-playing');await sleep(300);
  state.settings['Lock Playing Deck']=true;state.scratch[0][7].keylock=true;state.scratch[0][7].repeat=false;press(7,119);await until(()=>$('#notice').textContent.includes('Playing deck locked'),'Locked load refusal');report.lockedRefusal={track:d.track.id,keylock:d.keylock,repeat:d.repeat,playing:d.playing};assert(d.track===sample&&!d.keylock&&d.repeat&&d.playing,'Rejected Scratch Bank load changed deck settings');const locked=event('locked-load-keeps-playing');await sleep(250);
  click('#modal-close');click(button(0,'play'));await until(()=>!d.playing,'Pause sample');state.settings['Lock Playing Deck']=false;click('[data-panel="midi"]');press(7,127);await until(()=>d.track===original&&!d.processing,'Shift previous track');report.previous={id:d.track.id,position:engine.position(d),expected:previousPosition};assert(Math.abs(report.previous.position-previousPosition)<1e-6,'Previous source position lost');click('#modal-close');click(button(0,'play'));await until(()=>d.playing,'Play restored original');const restored=event('original-restored');await sleep(300);
  const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite PCM');
  report.audio=[['edited-loop',edited,400],['scratch-sample',samplePlaying,800],['locked-refusal',locked,800],['restored-original',restored,400]].map(([name,e,left])=>({name,expected:[left,550],channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.08,e.time+.20))}));for(const w of report.audio)w.channels.forEach((m,c)=>assert(m.rms>.005&&Math.abs(m.hz-w.expected[c])<.8,w.name+' expected audio carrier'));
  report.checks=['Actual Manual In/Out fine jog edit and visible edit states without tempo changes','Selected-slot save reaches stored metadata; next/previous focus and actual reloop','Scratch Bank UI cue/repeat settings load addressed deck and previous track','Playing-lock refusal preserves active source/settings; master recording matches all phases'];
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  for(const deck of state.decks)engine.pause(deck);if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};}}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#manual-original').textContent=JSON.stringify(report,null,2);$('#manual-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original JSON'}:null},null,2);$('#manual-status').textContent=report.completed?'Scoped Manual Loop/Scratch Bank workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');
 }
}
$('#manual-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#manual-run').disabled=false;$('#manual-run').textContent='Run one Manual Loop/Scratch Bank workflow';}
boot().catch(error=>$('#manual-status').textContent=error.message);
